00045 #pragma once
00046 #ifndef AI_COLOR4D_INL_INC
00047 #define AI_COLOR4D_INL_INC
00048 
00049 #ifdef __GNUC__
00050 #   pragma GCC system_header
00051 #endif
00052 
00053 #ifdef __cplusplus
00054 #include <assimp/color4.h>
00055 
00056 // ------------------------------------------------------------------------------------------------
00057 template <typename TReal>
00058 AI_FORCE_INLINE
00059 const aiColor4t<TReal>& aiColor4t<TReal>::operator += (const aiColor4t<TReal>& o) {
00060     r += o.r;
00061     g += o.g;
00062     b += o.b;
00063     a += o.a;
00064 
00065     return *this;
00066 }
00067 // ------------------------------------------------------------------------------------------------
00068 template <typename TReal>
00069 AI_FORCE_INLINE
00070 const aiColor4t<TReal>& aiColor4t<TReal>::operator -= (const aiColor4t<TReal>& o) {
00071     r -= o.r;
00072     g -= o.g;
00073     b -= o.b;
00074     a -= o.a;
00075 
00076     return *this;
00077 }
00078 // ------------------------------------------------------------------------------------------------
00079 template <typename TReal>
00080 AI_FORCE_INLINE
00081 const aiColor4t<TReal>& aiColor4t<TReal>::operator *= (TReal f) {
00082     r *= f;
00083     g *= f;
00084     b *= f;
00085     a *= f;
00086 
00087     return *this;
00088 }
00089 // ------------------------------------------------------------------------------------------------
00090 template <typename TReal>
00091 AI_FORCE_INLINE
00092 const aiColor4t<TReal>& aiColor4t<TReal>::operator /= (TReal f) {
00093     r /= f;
00094     g /= f;
00095     b /= f;
00096     a /= f;
00097 
00098     return *this;
00099 }
00100 // ------------------------------------------------------------------------------------------------
00101 template <typename TReal>
00102 AI_FORCE_INLINE
00103 TReal aiColor4t<TReal>::operator[](unsigned int i) const {
00104     switch ( i ) {
00105         case 0:
00106             return r;
00107         case 1:
00108             return g;
00109         case 2:
00110             return b;
00111         case 3:
00112             return a;
00113         default:
00114             break;
00115     }
00116     return r;
00117 }
00118 // ------------------------------------------------------------------------------------------------
00119 template <typename TReal>
00120 AI_FORCE_INLINE
00121 TReal& aiColor4t<TReal>::operator[](unsigned int i) {
00122     switch ( i ) {
00123         case 0:
00124             return r;
00125         case 1:
00126             return g;
00127         case 2:
00128             return b;
00129         case 3:
00130             return a;
00131         default:
00132             break;
00133     }
00134     return r;
00135 }
00136 // ------------------------------------------------------------------------------------------------
00137 template <typename TReal>
00138 AI_FORCE_INLINE
00139 bool aiColor4t<TReal>::operator== (const aiColor4t<TReal>& other) const {
00140     return r == other.r && g == other.g && b == other.b && a == other.a;
00141 }
00142 // ------------------------------------------------------------------------------------------------
00143 template <typename TReal>
00144 AI_FORCE_INLINE
00145 bool aiColor4t<TReal>::operator!= (const aiColor4t<TReal>& other) const {
00146     return r != other.r || g != other.g || b != other.b || a != other.a;
00147 }
00148 // ------------------------------------------------------------------------------------------------
00149 template <typename TReal>
00150 AI_FORCE_INLINE
00151 bool aiColor4t<TReal>::operator< (const aiColor4t<TReal>& other) const {
00152     return r < other.r || (
00153         r == other.r && (
00154             g < other.g || (
00155                 g == other.g && (
00156                     b < other.b || (
00157                         b == other.b && (
00158                             a < other.a
00159                         )
00160                     )
00161                 )
00162             )
00163         )
00164     );
00165 }
00166 
00167 // ------------------------------------------------------------------------------------------------
00168 template <typename TReal>
00169 AI_FORCE_INLINE
00170 aiColor4t<TReal> operator + (const aiColor4t<TReal>& v1, const aiColor4t<TReal>& v2)    {
00171     return aiColor4t<TReal>( v1.r + v2.r, v1.g + v2.g, v1.b + v2.b, v1.a + v2.a);
00172 }
00173 // ------------------------------------------------------------------------------------------------
00174 template <typename TReal>
00175 AI_FORCE_INLINE
00176 aiColor4t<TReal> operator - (const aiColor4t<TReal>& v1, const aiColor4t<TReal>& v2)    {
00177     return aiColor4t<TReal>( v1.r - v2.r, v1.g - v2.g, v1.b - v2.b, v1.a - v2.a);
00178 }
00179 // ------------------------------------------------------------------------------------------------
00180 template <typename TReal>
00181 AI_FORCE_INLINE aiColor4t<TReal> operator * (const aiColor4t<TReal>& v1, const aiColor4t<TReal>& v2)    {
00182     return aiColor4t<TReal>( v1.r * v2.r, v1.g * v2.g, v1.b * v2.b, v1.a * v2.a);
00183 }
00184 // ------------------------------------------------------------------------------------------------
00185 template <typename TReal>
00186 AI_FORCE_INLINE
00187 aiColor4t<TReal> operator / (const aiColor4t<TReal>& v1, const aiColor4t<TReal>& v2)    {
00188     return aiColor4t<TReal>( v1.r / v2.r, v1.g / v2.g, v1.b / v2.b, v1.a / v2.a);
00189 }
00190 // ------------------------------------------------------------------------------------------------
00191 template <typename TReal>
00192 AI_FORCE_INLINE
00193 aiColor4t<TReal> operator * ( TReal f, const aiColor4t<TReal>& v)   {
00194     return aiColor4t<TReal>( f*v.r, f*v.g, f*v.b, f*v.a);
00195 }
00196 // ------------------------------------------------------------------------------------------------
00197 template <typename TReal>
00198 AI_FORCE_INLINE
00199 aiColor4t<TReal> operator * ( const aiColor4t<TReal>& v, TReal f)  {
00200     return aiColor4t<TReal>( f*v.r, f*v.g, f*v.b, f*v.a);
00201 }
00202 // ------------------------------------------------------------------------------------------------
00203 template <typename TReal>
00204 AI_FORCE_INLINE
00205 aiColor4t<TReal> operator / ( const aiColor4t<TReal>& v, TReal f)  {
00206     return v * (1/f);
00207 }
00208 // ------------------------------------------------------------------------------------------------
00209 template <typename TReal>
00210 AI_FORCE_INLINE
00211 aiColor4t<TReal> operator / ( TReal f,const aiColor4t<TReal>& v)   {
00212     return aiColor4t<TReal>(f,f,f,f)/v;
00213 }
00214 // ------------------------------------------------------------------------------------------------
00215 template <typename TReal>
00216 AI_FORCE_INLINE
00217 aiColor4t<TReal> operator + ( const aiColor4t<TReal>& v, TReal f)  {
00218     return aiColor4t<TReal>( f+v.r, f+v.g, f+v.b, f+v.a);
00219 }
00220 // ------------------------------------------------------------------------------------------------
00221 template <typename TReal>
00222 AI_FORCE_INLINE
00223 aiColor4t<TReal> operator - ( const aiColor4t<TReal>& v, TReal f)  {
00224     return aiColor4t<TReal>( v.r-f, v.g-f, v.b-f, v.a-f);
00225 }
00226 // ------------------------------------------------------------------------------------------------
00227 template <typename TReal>
00228 AI_FORCE_INLINE
00229 aiColor4t<TReal> operator + ( TReal f, const aiColor4t<TReal>& v)  {
00230     return aiColor4t<TReal>( f+v.r, f+v.g, f+v.b, f+v.a);
00231 }
00232 // ------------------------------------------------------------------------------------------------
00233 template <typename TReal>
00234 AI_FORCE_INLINE
00235 aiColor4t<TReal> operator - ( TReal f, const aiColor4t<TReal>& v)  {
00236     return aiColor4t<TReal>( f-v.r, f-v.g, f-v.b, f-v.a);
00237 }
00238 
00239 // ------------------------------------------------------------------------------------------------
00240 template <typename TReal>
00241 AI_FORCE_INLINE
00242 bool aiColor4t<TReal>::IsBlack() const {
00243     // The alpha component doesn't care here. black is black.
00244     static const TReal epsilon = 10e-3f;
00245     return std::fabs( r ) < epsilon && std::fabs( g ) < epsilon && std::fabs( b ) < epsilon;
00246 }
